-- Step 8: centrally managed operating configuration.
create table if not exists public.crm_tax_rates(company_state_id text not null default public.crm_base_state_id(),id text not null,name text not null,rate numeric(8,5) not null check(rate between 0 and 1),active boolean not null default true,is_default boolean not null default false,created_by uuid not null default auth.uid(),updated_by uuid not null default auth.uid(),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(company_state_id,id),unique(company_state_id,name));
create table if not exists public.crm_payment_methods(company_state_id text not null default public.crm_base_state_id(),id text not null,name text not null,display_order integer not null default 0,active boolean not null default true,requires_reference boolean not null default false,created_by uuid not null default auth.uid(),updated_by uuid not null default auth.uid(),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(company_state_id,id),unique(company_state_id,name));
create table if not exists public.crm_role_capabilities(company_state_id text not null default public.crm_base_state_id(),role_name text not null,capability text not null,allowed boolean not null default false,updated_by uuid not null default auth.uid(),updated_at timestamptz not null default clock_timestamp(),primary key(company_state_id,role_name,capability));
create table if not exists public.crm_announcements(company_state_id text not null default public.crm_base_state_id(),id text not null,title text not null,body text not null,audience_role text not null default 'all',starts_at timestamptz not null default clock_timestamp(),ends_at timestamptz,dismissible boolean not null default true,active boolean not null default true,created_by uuid not null default auth.uid(),updated_by uuid not null default auth.uid(),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(company_state_id,id));
create table if not exists public.crm_operational_settings(company_state_id text not null default public.crm_base_state_id(),setting_key text not null,value jsonb not null default '{}'::jsonb,updated_by uuid not null default auth.uid(),updated_at timestamptz not null default clock_timestamp(),primary key(company_state_id,setting_key));
do $$declare t text;begin foreach t in array array['crm_tax_rates','crm_payment_methods','crm_role_capabilities','crm_announcements','crm_operational_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('drop policy if exists "CRM users read admin configuration" on public.%I',t);execute format('drop policy if exists "CRM admins insert admin configuration" on public.%I',t);execute format('drop policy if exists "CRM admins update admin configuration" on public.%I',t);execute format('create policy "CRM users read admin configuration" on public.%I for select to authenticated using(public.is_coastal_crest_user() and company_state_id=public.crm_base_state_id())',t);execute format('create policy "CRM admins insert admin configuration" on public.%I for insert to authenticated with check(public.is_crm_admin() and company_state_id=public.crm_base_state_id())',t);execute format('create policy "CRM admins update admin configuration" on public.%I for update to authenticated using(public.is_crm_admin() and company_state_id=public.crm_base_state_id()) with check(public.is_crm_admin() and company_state_id=public.crm_base_state_id())',t);execute format('grant select,insert,update on public.%I to authenticated',t);end loop;end$$;
insert into public.crm_payment_methods(company_state_id,id,name,display_order,requires_reference,created_by,updated_by) values
(public.crm_base_state_id(),'check','Check',10,true,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000'),(public.crm_base_state_id(),'cash','Cash',20,false,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000'),(public.crm_base_state_id(),'ach','ACH',30,true,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000'),(public.crm_base_state_id(),'card','Card',40,true,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000'),(public.crm_base_state_id(),'financing','Financing',50,true,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000'),(public.crm_base_state_id(),'other','Other',60,true,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000') on conflict(company_state_id,id) do nothing;
